from __future__ import absolute_import
from selenium.common.exceptions import StaleElementReferenceException
from taf.selenium.sbts.pages.configuration import configuration_management


class ConfigurationCommonAction(configuration_management.common.ConfigurationCommonAction):

    def _choose_object(self, object_name_list, bts_configuration):
        try:
            elem = self._go_to_target_object(bts_configuration, object_name_list)
            self.driver.execute_script("arguments[0].scrollIntoView();", elem)
        except StaleElementReferenceException:
            """
            The exception is caused because the element is exipred.
            It is always caused by the page refresh or the page is changed.
            So need to find the element again here.
            """
            elem = self._go_to_target_object(bts_configuration, object_name_list)
            self.driver.execute_script("arguments[0].scrollIntoView();", elem)

        elem.click()
